import {esc,fmt,initials} from './lib.js';
import {portrait,portraitFor} from './photos.js';

const hammer=`<svg viewBox="0 0 32 32" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="m12 6 4-4 10 10-4 4zM10 8l10 10M9 9l-3 3 9 9 3-3M14 19 4 29M2 30h28M22 27h7v3"/></g></svg>`;

export function cinemaToolbar(){return `<div class="cinema-toolbar"><div class="cinema-wordmark"><span class="cinema-monogram">RR</span><div><strong>THE ROYAL ROOM</strong><small>A PRESSURE LAB PRESENTATION</small></div></div><div class="cinema-controls"><button data-replay-entrance aria-label="Replay cinematic entrance" title="Replay entrance">↻ <span>Replay intro</span></button><button data-cinema-motion aria-pressed="false" aria-label="Pause decorative effects" title="Pause decorative effects">◉ <span>Effects on</span></button><button data-showreel-toggle aria-pressed="false">▷ <span>Play showreel</span></button><button data-cinema-toggle aria-pressed="false" class="cinema-enter">⛶ <span>Cinema view</span></button></div></div>`;}

export function openingMarkup(){return `<div class="cinema-opening" aria-hidden="true"><div class="opening-door door-left"></div><div class="opening-door door-right"></div><div class="opening-type"><span>RAJASTHAN ROYALS INSPIRED</span><strong>ALL EYES.<br><em>ON THE EVIDENCE.</em></strong><small>SUPERR SELECTOR · SEASON 02</small></div><div class="opening-streak"></div></div>`;}

const stadium=`<div class="cinema-stadium" aria-hidden="true"><svg viewBox="0 0 1200 650" preserveAspectRatio="xMidYMid slice"><defs><pattern id="stadiumSeats" width="22" height="17" patternUnits="userSpaceOnUse"><rect x="4" y="4" width="7" height="3" rx="1" fill="#d2c4f1" opacity=".16"/></pattern><linearGradient id="stadiumFade" x2="0" y2="1"><stop stop-color="#15182e" stop-opacity="0"/><stop offset="1" stop-color="#080c20"/></linearGradient><linearGradient id="stadiumLed"><stop stop-color="#ff49a0" stop-opacity="0"/><stop offset=".35" stop-color="#ff49a0"/><stop offset=".7" stop-color="#8da6ff"/><stop offset="1" stop-color="#8da6ff" stop-opacity="0"/></linearGradient></defs><path d="M-80 170Q600 460 1280 170v270H-80Z" fill="#1d2341"/><path d="M-80 175Q600 465 1280 175v260H-80Z" fill="url(#stadiumSeats)"/><path d="M-80 173Q600 463 1280 173M-80 205Q600 495 1280 205M-80 237Q600 527 1280 237M-80 269Q600 559 1280 269" fill="none" stroke="#8595cb" opacity=".12"/><path d="M-80 310Q600 595 1280 310" fill="none" stroke="url(#stadiumLed)" stroke-width="3"/><path d="M-80 336Q600 621 1280 336" fill="none" stroke="#a9b5ec" stroke-width="1" opacity=".12"/><path d="M0 50Q600 350 1200 50" fill="none" stroke="#7787be" opacity=".12"/><path d="M0 54Q600 354 1200 54" fill="none" stroke="#b9c4e7" opacity=".06" stroke-width="12"/><path d="M0 0h1200v650H0Z" fill="url(#stadiumFade)"/></svg><div class="stadium-led"></div><div class="floodlight-bank floodlight-left">${'<i></i>'.repeat(8)}</div><div class="floodlight-bank floodlight-right">${'<i></i>'.repeat(8)}</div></div>`;

export function decorateStage(markup,p,{intro=false,direction='next',flipped=false}={}){
  const fullName=esc(p.shortName),surname=esc(p.shortName.split(' ').at(-1));
  const name=`<h2 class="broadcast-player-name" aria-label="${fullName}">${p.shortName.split(' ').map((word,i)=>`<span aria-hidden="true" style="--word:${i}">${esc(word)}</span>`).join(' ')}</h2>`;
  const atmosphere=`${stadium}<div class="cinema-anamorphic" aria-hidden="true"></div><div class="cinema-grain" aria-hidden="true"></div><div class="cinema-vignette" aria-hidden="true"></div><span class="stage-surname" aria-hidden="true">${surname}</span><span class="stage-frame frame-tl" aria-hidden="true"></span><span class="stage-frame frame-tr" aria-hidden="true"></span><span class="stage-frame frame-bl" aria-hidden="true"></span><span class="stage-frame frame-br" aria-hidden="true"></span><div class="stage-broadcast-label" aria-hidden="true">${hammer}<span>THE ROYAL ROOM<small>PLAYER EVIDENCE SERIES</small></span></div>${intro?openingMarkup():''}`;
  let rendered=markup.replace(`class="auction-stage ${p.role}"`,`class="auction-stage ${p.role} cinema-stage ${portraitFor(p)?'has-player-photo':''}" data-direction="${direction}"`).replace('<div class="stage-grid"',`${atmosphere}<div class="stage-grid"`).replace(`<h2>${fullName}</h2>`,name).replace('<div class="card-pedestal" aria-hidden="true"></div>','<div class="card-pedestal" aria-hidden="true"></div><div class="auction-plinth" aria-hidden="true"><span>SUPERR</span><small>PRESSURE LAB / ROUND 01</small></div>').replace('<span class="stage-browse-label">','<span class="stage-browse-label"><i class="broadcast-signal" aria-hidden="true"></i>');
  if(portraitFor(p))rendered=rendered.replace(/<div class="jersey-art" aria-hidden="true">[\s\S]*?<\/div>/,`<div class="portrait-art" aria-hidden="true">${portrait(p,{className:'card-player-photo',loading:'eager'})}<span class="photo-fallback-label">Portrait unavailable</span></div>`);
  rendered=rendered.replace('<div class="spotlight-card">',`<div class="spotlight-card" role="button" tabindex="0" data-card-flip aria-pressed="${flipped}" aria-label="${fullName}: ${flipped?'show player portrait':'show player evidence'}" title="Click or tap to flip. Enter or Space also works.">`);
  return rendered;
}

export function playerVault(players,role,selected){
  const picks=players.filter(p=>p.role===role&&p.rank<=10).sort((a,b)=>a.rank-b.rank);
  return `<div class="vault-heading"><div><span class="eyebrow">THE PLAYER VAULT</span><h2>Ten cards. Every detail matters.</h2></div><span class="vault-hint">SCROLL TO EXPLORE <b>⟶</b></span></div><div class="spotlight-rail" tabindex="0" aria-label="${role==='bat'?'Batting':'Bowling'} player cards; scroll horizontally">${picks.map((p,i)=>`<button class="rail-card ${p.role} ${i===selected?'is-selected':''}" data-spotlight-index="${i}" aria-pressed="${i===selected}" aria-label="Spotlight ${esc(p.shortName)}, official rank ${p.rank}"><span class="rail-rank">${String(p.rank).padStart(2,'0')}<small>${p.role==='bat'?'BAT':'BOWL'}</small></span>${portraitFor(p)?portrait(p,{className:'rail-portrait'}):`<span class="rail-watermark" aria-hidden="true">${esc(initials(p.shortName))}</span>`}<span class="rail-player">${esc(p.shortName)}</span><span class="rail-bottom"><strong>${fmt(p.score,2)}</strong><small>INDEX<br>POINTS</small><i>${i===selected?'↗':'+'}</i></span><span class="rail-selected-label">${i===selected?'IN THE SPOTLIGHT':'VIEW PLAYER'}</span></button>`).join('')}</div>`;
}
